INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502003,'私人定制游','1、旅行社总社需提供：①《旅行社业务经营许可证》；②旅行社责任险保险单 。 2、旅行社分社需提供：①旅行社分社备案登记证明； ②旅行社责任险保险单（若为总社统一购买提供总社旅行社责任险保险单）；③总社的《旅行社业务经营许可证》； ④旅行社分社和总社补充协议（如：由总社出具的知情同意责任书）。 3、旅行社若经营“境外一日游/多日游”“潜水”、“境外玩乐套餐”、“接送（机场/点对点/拼车）”类目，除提供上述资质外，还须提供至少一份与实际服务提供方的有效合作协议',1,'',0,525002,'旅游度假',128209,'旅游休闲' FROM DUAL WHERE @ok_flag;
INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502005,'定金','1、如主体为汽车厂商需提供《营业执照》和《工信部道路机动车辆生产企业准入许可》； 2、如主体为汽车经销商/4s店需提供《营业执照》和《厂商授权销售文件》与《工信部道路机动车辆生产企业准入许可》； 3、如主体为下属子/分公司需提供《营业执照》、《工信部道路机动车辆生产企业准入许可》与《股权关系证明函》（含双方盖章）； 注：需提供线下门店照片',1,'请商详中说明定金具体规则，并在商品标题中注明（定金）',2,378068,'汽车服务',6263,'汽车' FROM DUAL WHERE @ok_flag;
