INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502007,'流量充值','运营商主体：需提供《基础电信业务经营许可证》 非运营商主体：提供运营商（移动、联通、电信）的代理合同或合作协议等正规渠道证明（协议需含代理范围/代理产品）',1,'',0,1966,'通信服务',377078,'生活服务' FROM DUAL WHERE @ok_flag;
INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502009,'金条','1、需提供申请主体《营业执照》（经营范围包括销售黄金制品等） 2、需提供1款由国/省/市级质监局或同级别检测机构出具的完整的相关质检/检测报告。报告需包含：① CMA或CNAS标识；② 商标/商品图、检测单位、商品成分各含量鉴定结论',1,'商品介绍应当对可能存在的风险以及风险责任承担有合理提示或者警示，不得对收益或者与其相关的情况作出保证性承诺，不得利用学术机构、行业协会、专业人士、受益者的名义或者形象作推荐、证明',2,378137,'黄金',378136,'珠宝首饰' FROM DUAL WHERE @ok_flag;
