INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502044,'菌/菇/酵素','需提供： 1、 《食品经营许可证》或《预包装食品销售备案凭证》。 2、① 报关单：需提供近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若报关单上的经营使用单位或收货单位不在授权链上，需同时提供委托进口协议）；② 入境货物检验检疫证明：需提供与报关单合同协议号一致的检验检疫证明。',1,'1、2选1：①  需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明产品可以普通食品身份进入市场。② 《进口保健食品批准证书》 2、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。',1,530056,'海外膳食营养补充食品',502043,'膳食营养补充食品' FROM DUAL WHERE @ok_flag;
INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502045,'植物精华/提取物','需提供： 1、 《食品经营许可证》或《预包装食品销售备案凭证》。 2、① 报关单：需提供近一年内的中华人民共和国海关进口货物报关单，报关单上应展现对应品牌名称，及商品名称；（若报关单上的经营使用单位或收货单位不在授权链上，需同时提供委托进口协议）；② 入境货物检验检疫证明：需提供与报关单合同协议号一致的检验检疫证明。',1,'1、2选1：①  需提供生产商在当地质量技术监督局进行的食品安全企业标准备案，证明产品可以普通食品身份进入市场。② 《进口保健食品批准证书》 2、如涉及特殊用途膳食用食品的，需提供《国产特殊医学用途配方食品批准证书》或《婴儿配方乳粉注册证书》。 特殊用途膳食用食品：指涉及医学用途或婴幼儿配方的食品。',1,530056,'海外膳食营养补充食品',502043,'膳食营养补充食品' FROM DUAL WHERE @ok_flag;
