INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 502050,'蹦床','1、 《营业执照》。 2、 《娱乐场所经营许可证》。',1,'',0,428007,'本地玩乐',128209,'旅游休闲' FROM DUAL WHERE @ok_flag;
