INSERT INTO `eb_pay_component_cat` (`third_cat_id`, `third_cat_name`, `qualification`, `qualification_type`, `product_qualification`, `product_qualification_type`, `second_cat_id`, `second_cat_name`, `first_cat_id`, `first_cat_name`) SELECT 529051,'机票','1、航空公司主体，需提供①《公共航空运输企业经营许可证》；② 《ICP许可证》。 2、  非航空主体，需提供：①《营业执照》经营范围包含：机票销售代理业务或相同意思表示；② 与航空公司的合作协议/授权代理销售协议；③《ICP许可证》。',1,'',0,496042,'票务',530004,'出行与交通' FROM DUAL WHERE @ok_flag;
